<script setup lang="ts">
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsolePagePathPicker from './ConsolePagePathPicker.vue'
import DecorationColorField from './DecorationColorField.vue'
import DecorationVisualPicker from './DecorationVisualPicker.vue'
import {decorationIconUrl} from '../../../../api/src/core/decoration-framework.mjs'
import {decorationLinkLabel} from '../../../../api/src/core/decoration-links.mjs'
import type {DecorationItem,DecorationScheme,DecorationRoute} from '../../../../api/src/core/decoration-types'
const props=defineProps<{targets:DecorationRoute[];disabled?:boolean;imageUrl:(id:string)=>string}>()
const nav=defineModel<DecorationScheme['navigation']>({required:true})
defineEmits<{pick:[id:string]}>()
const selected=ref(nav.value.items[0]?.id||''),dragId=ref(''),adding=ref<DecorationItem|null>(null)
const item=computed(()=>adding.value||nav.value.items.find(i=>i.id===selected.value))
function add(){if(props.disabled||nav.value.items.length>=5)return;adding.value={id:crypto.randomUUID(),label:'',target:'',imageId:null}}
function preset(key:string){if(!adding.value||props.disabled)return;const target=props.targets.find(t=>t.key===key);if(target){adding.value.label=key==='profile'?'我的':target.label;adding.value.target=key}}
function finishAdd(){if(props.disabled||!adding.value?.label.trim()||!adding.value.target||nav.value.items.length>=5)return;const entry={...adding.value,label:adding.value.label.trim()},empty=nav.value.items.length===0;nav.value.items.push(entry);selected.value=entry.id;adding.value=null;if(empty)nav.value.enabled=true}
function remove(index:number){if(props.disabled)return;nav.value.items.splice(index,1);selected.value=nav.value.items[0]?.id||'';if(!nav.value.items.length)nav.value.enabled=false}
function move(index:number,offset:number){if(props.disabled||index+offset<0||index+offset>=nav.value.items.length)return;const [value]=nav.value.items.splice(index,1);nav.value.items.splice(index+offset,0,value!)}
function drop(id:string){if(props.disabled||!dragId.value||dragId.value===id)return;const from=nav.value.items.findIndex(i=>i.id===dragId.value),to=nav.value.items.findIndex(i=>i.id===id);if(from<0||to<0)return;const [item]=nav.value.items.splice(from,1);nav.value.items.splice(to,0,item!);dragId.value=''}
</script>
<template><div class="navigation-panel"><label class="navigation-switch"><span>显示底部导航</span><USwitch v-model="nav.enabled" :disabled="disabled||!nav.items.length" aria-label="显示底部导航"/></label><div class="navigation-items"><div v-for="(entry,index) in nav.items" :key="entry.id" :class="{active:entry.id===selected}" :draggable="!disabled" @dragstart="dragId=entry.id;$event.dataTransfer?.setData('text/plain',entry.id)" @dragend="dragId=''" @dragover.prevent @drop.prevent="drop(entry.id)"><UIcon name="i-lucide-grip-vertical" class="navigation-grip" title="拖动排序"/><button type="button" :disabled="!!adding" @click="selected=entry.id"><img v-if="entry.imageId||entry.icon" :src="entry.imageId?imageUrl(entry.imageId):decorationIconUrl(entry.icon)" alt=""><UIcon v-else :name="entry.target==='home'?'i-lucide-house':entry.target==='profile'?'i-lucide-user-round':'i-lucide-layout-grid'"/><span>{{entry.label}}<small>{{decorationLinkLabel(entry.target,targets)}}</small></span></button><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-chevron-up" aria-label="上移导航" :disabled="disabled||index===0" @click="move(index,-1)"/><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-chevron-down" aria-label="下移导航" :disabled="disabled||index===nav.items.length-1" @click="move(index,1)"/><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-x" aria-label="删除导航" :disabled="disabled" @click="remove(index)"/></div></div><UButton color="neutral" variant="outline" icon="i-lucide-plus" :disabled="disabled||nav.items.length>=5||!!adding" @click="add">添加导航（{{nav.items.length}}/5）</UButton><section v-if="item" class="navigation-detail"><h3>{{adding?'新增导航':'当前导航项'}}</h3><div v-if="adding" class="navigation-presets"><span>快捷填入</span><button v-for="target in targets.filter(t=>['home','profile'].includes(t.key))" :key="target.key" type="button" @click="preset(target.key)">{{target.key==='profile'?'我的':target.label}}</button></div><label class="block text-xs text-muted space-y-2"><span>名称</span><ConsoleInput v-model="item.label" placeholder="填写导航名称" :maxlength="12" :disabled="disabled"/></label><div v-if="!adding" class="space-y-2"><DecorationVisualPicker v-model:image-id="item.imageId" v-model:icon="item.icon" label="导航图标" :fallback-icon="item.target==='home'?'house':item.target==='profile'?'user-round':'layout-grid'" :image-url="imageUrl" :disabled="disabled" @pick="$emit('pick',item.id)"/></div><ConsolePagePathPicker v-model="item.target" :options="targets" :disabled="disabled" :allow-empty="false"/><div v-if="adding" class="flex gap-2 justify-end"><UButton color="neutral" variant="outline" @click="adding=null">取消</UButton><UButton :disabled="disabled||!adding.label.trim()||!adding.target" @click="finishAdd">确认添加</UButton></div></section><section class="navigation-detail"><h3>导航样式</h3><label class="navigation-switch"><span>跟随主题风格</span><USwitch v-model="nav.inheritTheme" :disabled="disabled" aria-label="导航跟随主题"/></label><template v-if="!nav.inheritTheme"><DecorationColorField v-model="nav.background" label="背景颜色" :disabled="disabled"/><DecorationColorField v-model="nav.color" label="默认颜色" :disabled="disabled"/><DecorationColorField v-model="nav.selectedColor" label="选中颜色" :disabled="disabled"/></template></section></div></template>
<style scoped>.navigation-panel{display:grid;gap:16px}.navigation-switch{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.navigation-items{display:grid;gap:8px}.navigation-items>div{display:flex;align-items:center;gap:0;border:1px solid var(--ui-border);border-radius:8px;padding:5px}.navigation-items>div.active{border-color:var(--ui-primary);background:color-mix(in srgb,var(--ui-primary) 4%,var(--ui-bg))}.navigation-items>div>button:first-child{flex:1;display:flex;align-items:center;gap:10px;padding:5px;min-width:0;text-align:left}.navigation-items img,.navigation-items .iconify{width:22px;height:22px;object-fit:contain;flex-shrink:0}.navigation-items span{font-size:12px;min-width:0;overflow:hidden;text-overflow:ellipsis}.navigation-items small{display:block;font-size:10px;color:var(--ui-text-muted);margin-top:3px}.navigation-detail{border-top:1px solid var(--ui-border);padding-top:20px;display:grid;gap:14px}.navigation-detail h3{font-size:13px;font-weight:600}.navigation-grip{font-size:14px!important;width:14px!important;height:18px!important;cursor:grab;color:var(--ui-text-dimmed);flex-shrink:0}.navigation-items>div>button:first-of-type{flex:1;display:flex;align-items:center;gap:10px;padding:5px;min-width:0;text-align:left}
.navigation-presets{display:flex;align-items:center;gap:8px;font-size:12px}.navigation-presets>span{color:var(--ui-text-muted);margin-right:4px}.navigation-presets button{border:1px solid var(--ui-border);padding:5px 12px;border-radius:5px}.navigation-presets button:hover{border-color:var(--ui-primary);color:var(--ui-primary)}
</style>
